142	     *  settling by the user who opened the claim (403), settling a PENDING claim (409: it is
143	     *  approved or rejected instead), and any move of a claim dated in a closed period (423). A
144	     *  clerk settling a claim whose due is above the sheet's clerk limit sends it to PENDING. */
145	    @Transactional
146	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus to) {
147	        Claim claim = claims.findForUpdate(id, sheetId)
148	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
149	        refuseIfClosed(sheetId, claim.getDate());
150	        if (to == ClaimStatus.PENDING || (to == ClaimStatus.SETTLED && claim.getStatus() == ClaimStatus.PENDING)
151	                || !claim.getStatus().canMoveTo(to)) {
152	            throw new ResponseStatusException(HttpStatus.CONFLICT,
153	                    "A " + claim.getStatus() + " claim cannot become " + to);
154	        }
155	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
156	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
157	                    "The user who opened a claim cannot settle it");
158	        }
159	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
160	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
161	        // a claim bound by a statement settles at its bound figure, its late charge frozen in
162	        BigDecimal settling = to == ClaimStatus.SETTLED ? shownDueOf(claim, person) : null;
163	        if (to == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, settling)) {
164	            // above the clerk limit: a steward approves or rejects it
165	            to = ClaimStatus.PENDING;
