234	     *  closed period, (409) unless PENDING, and (403) when the user is not a steward. */
235	    private Claim pendingForSteward(String sheetId, String user, long id) {
236	        Claim claim = claims.findForUpdate(id, sheetId)
237	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
238	        refuseIfClosed(sheetId, claim.getDate());
239	        if (claim.getStatus() != ClaimStatus.PENDING) {
240	            throw new ResponseStatusException(HttpStatus.CONFLICT,
241	                    "Only a PENDING claim is approved or rejected, not a " + claim.getStatus() + " one");
242	        }
243	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
244	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
245	                    "Only a steward approves or rejects a PENDING claim");
246	        }
247	        return claim;
248	    }
