254	    /** Take a statement of a person: record their due-total now, and bind each of their claims
255	     *  that counts (OPEN, PENDING or SETTLED, of a held person only SETTLED) to its figure now; the others
256	     *  are left unbound. */
257	    @Transactional
258	    public Statement statement(String sheetId, String user, long personId) {
259	        Person person = people.findForUpdate(personId, sheetId)
260	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
261	        LocalDate today = sheets.today(sheetId);
262	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
263	        RollupService.Snapshot before = rollup.snapshot(sheetId);
264	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person)).toList();
265	        BigDecimal dueTotal = dueTotalOf(counted, person, today);
266	        for (Claim c : theirs) {
267	            if (counts(c, person)) {
268	                // the statement binds the figure; the late charge keeps following the sheet's today
269	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
270	            } else {
271	                c.unbind();
272	            }
273	        }
274	        claims.flush();
275	        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
276	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
277	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
278	        rollup.recordChanges(sheetId, user, before);
279	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
280	    }
281	
282	    /** The number a claim dated {@code date} takes as it is opened: under period numbering (set,
283	     *  and the sheet's today on or after it) the next within the period containing the date
284	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number. */
285	    private String nextNumber(String sheetId, LocalDate date) {
286	        if (!sheets.periodNumberingOn(sheetId)) {
287	            return String.valueOf(sheets.nextClaimNumber(sheetId));
288	        }
289	        // held until the transaction ends, so two claims opened at once are numbered one after the other
290	        sheets.lock(sheetId);
291	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
292	        int last = claims.findNumbers(sheetId).stream()
293	                .filter(n -> n.startsWith(prefix))
294	                .map(n -> n.substring(prefix.length()))
295	                .filter(n -> n.matches("\\d{1,9}"))
296	                .mapToInt(Integer::parseInt)
297	                .max().orElse(0);
298	        return prefix + (last + 1);
299	    }
300	
301	    /** Refuse (423) a change to a claim dated in a closed period, holding the sheet locked until
302	     *  the transaction ends so a period cannot be closed meanwhile. */
303	    private void refuseIfClosed(String sheetId, LocalDate date) {
304	        sheets.lock(sheetId);
305	        periods.refuseIfClosed(sheetId, date);
306	    }
307	
308	    /** The number a claim of the amount corrects: none unless the amount is negative, when it must
309	     *  be the number of a SETTLED claim of the same person, or the claim is refused (422). */
310	    private String correctedBy(String sheetId, long personId, BigDecimal amount, String corrects) {
311	        if (amount.signum() >= 0) {
312	            return null;
313	        }
314	        if (corrects == null
315	                || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
316	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
317	                    "A negative amount must correct a settled claim of the same person");
318	        }
319	        return corrects;
320	    }
321	
322	    /** Refuse (422) a claim dated after its person's retirement date. */
323	    private static void refuseIfRetired(Person person, LocalDate date) {
324	        if (person.retiredBefore(date)) {
325	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
326	                    "The date is after the person's retirement date");
327	        }
328	    }
329	
330	    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
331	     *  do, and of a held person only SETTLED ones. */
332	    private static boolean counts(Claim c, Person person) {
333	        return c.getStatus() == ClaimStatus.SETTLED
334	                || (c.getStatus().isOpen() && !person.isHeld());
335	    }
336	
337	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
338	     *  charge on top. */
339	    private BigDecimal shownDueOf(Claim claim, Person person) {
340	        if (claim.getSettledDue() != null) {
341	            return claim.getSettledDue();
342	        }
343	        return LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, figureOf(claim, person), roundingOf(claim));
344	    }
345	
346	    /** A claim's figure before any late charge: the one a statement bound it to (null: n/a), else
347	     *  (unbound, or PENDING) its live due. */
348	    private BigDecimal figureOf(Claim claim, Person person) {
349	        return claim.isBound() ? claim.getStatedDue() : dueOf(claim, person);
350	    }
351	
352	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
353	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
354	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
355	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
356	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
357	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
358	            return null;
359	        }
360	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
361	    }
362	
363	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
364	     *  100, rounded as its rounding policy has it, raised to the sheet's floor (a correction's never is); null with no rate in force then. */
365	    private BigDecimal dueOf(Claim claim, Person person) {
366	        BigDecimal floor = sheets.floor(claim.getSheetId());
367	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
368	                .map(Rate::getPct)
369	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
370	                .map(due -> claim.isCorrection() ? due : due.max(floor))
371	                .orElse(null);
372	    }
373	
374	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
375	     *  correction the date of the claim it corrects. */
376	    private RoundingMode roundingOf(Claim claim) {
377	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
378	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
379	                        .map(Claim::getDate).orElse(claim.getDate());
380	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
381	    }
382	
383	    private void record(String event, String user, Person person, Claim claim) {
384	        record(event, user, person, claim, claim.getNumber());
385	    }
386	
387	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
388	    private void record(String event, String user, Person person, Claim claim, String number) {
389	        record(event, user, person, claim, number, "");
390	    }
391	
392	    private void record(String event, String user, Person person, Claim claim, String number, String extra) {
393	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
394	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
395	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
396	    }
397	
398	    private static String noteOf(String note) {
399	        return note == null ? "" : note.trim();
400	    }
401	}
