import { Component, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { Period, periodOn } from '../periods/periods-api';
import { DatedGrade, gradeOn } from '../people/people-api';
import { Rate, claimDueCents } from '../rates/rates-api';
import { CLAIM_AMOUNT_PATTERN, Claim, ClaimAction, ClaimsApi, cents, claimError, dueBy, money, overdue, roundsHalfUp, statusError } from './claims-api';

// One person's claims, newest first, and the one form that adds a claim or, with a claim's
// editor open, saves that claim.
@Component({
  selector: 'app-person-claims',
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="form" (ngSubmit)="submit()"
      [attr.aria-label]="(editingId() === null ? 'Add claim for ' : 'Edit claim for ') + personName()">
      <label [for]="fieldId('amount')">Amount</label>
      <input [id]="fieldId('amount')" data-testid="claim-form-amount" formControlName="amount"
        inputmode="decimal" autocomplete="off" />
      <label [for]="fieldId('date')">Date</label>
      <input [id]="fieldId('date')" type="date" data-testid="claim-form-date" formControlName="date" />
      <label [for]="fieldId('note')">Note</label>
      <input [id]="fieldId('note')" data-testid="claim-form-note" formControlName="note" autocomplete="off" />
      <label [for]="fieldId('corrects')">Corrects claim no.</label>
      <input [id]="fieldId('corrects')" data-testid="claim-form-corrects" formControlName="corrects"
        autocomplete="off" />
      <button type="submit" data-testid="claim-form-submit">{{ editingId() === null ? 'Add claim' : 'Save claim' }}</button>
      @if (error(); as err) {
        <p role="alert" data-testid="claim-form-error">{{ err }}</p>
      }
    </form>
    @if (claims().length > 0) {
      <ul [attr.aria-label]="'Claims of ' + personName()">
        @for (c of claims(); track c.id) {
          <li [attr.data-testid]="'claim-row-' + c.id">
            <input type="checkbox" data-testid="claim-select" [checked]="selected().has(c.id)"
              (change)="toggled.emit({ id: c.id, on: $any($event.target).checked })"
              [attr.aria-label]="'Select claim of ' + c.amount + ' on ' + c.date" />
            <span>No. <span data-testid="claim-number">{{ c.number ?? '' }}</span></span>
            <span data-testid="claim-amount">{{ c.amount }}</span>
            <span data-testid="claim-date">{{ c.date }}</span>
            <span data-testid="claim-note">{{ c.note }}</span>
            <span>Corrects No. <span data-testid="claim-corrects">{{ c.corrects ?? '' }}</span></span>
            <span>Due <span data-testid="claim-due">{{ dueOf(c) }}</span></span>
            <span>Status <span data-testid="claim-status">{{ c.status }}</span></span>
            <span>Opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span></span>
            <span>Stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span></span>
            <span>Period <span data-testid="claim-period">{{ periodOf(c) }}</span></span>
            <span>Due by <span data-testid="claim-due-by">{{ dueByOf(c) }}</span></span>
            <span>Overdue <span data-testid="claim-overdue">{{ overdueOf(c) ? 'yes' : 'no' }}</span></span>
            <button type="button" data-testid="claim-open" (click)="changeStatus(c, 'open')"
              [attr.aria-label]="'Open claim of ' + c.amount + ' on ' + c.date">Open</button>
            <button type="button" data-testid="claim-settle" (click)="changeStatus(c, 'settle')"
              [attr.aria-label]="'Settle claim of ' + c.amount + ' on ' + c.date">Settle</button>
            <button type="button" data-testid="claim-approve" (click)="changeStatus(c, 'approve')"
              [attr.aria-label]="'Approve claim of ' + c.amount + ' on ' + c.date">Approve</button>
            <label [for]="'claim-reject-reason-' + c.id">Reject reason</label>
            <input [id]="'claim-reject-reason-' + c.id" data-testid="claim-reject-reason" autocomplete="off"
              [value]="rejectReasons()[c.id] ?? ''" (input)="reasonChanged(c.id, $any($event.target).value)" />
            <button type="button" data-testid="claim-reject" (click)="reject(c)"
              [attr.aria-label]="'Reject claim of ' + c.amount + ' on ' + c.date">Reject</button>
            <button type="button" data-testid="claim-void" (click)="changeStatus(c, 'void')"
              [attr.aria-label]="'Void claim of ' + c.amount + ' on ' + c.date">Void</button>
            <button type="button" data-testid="claim-edit" (click)="edit(c)"
              [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
            @if (editingId() === c.id) {
              <button type="button" data-testid="claim-cancel" (click)="reset()">Cancel</button>
            }
            @if (rowErrors()[c.id]; as err) {
              <p role="alert" data-testid="claim-error">{{ err }}</p>
            }
          </li>
        }
      </ul>
    }
  `,
})
export class PersonClaims {
  private readonly session = inject(Session);
  private readonly api = inject(ClaimsApi);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  /** This person's claims, newest first. */
  readonly claims = input.required<Claim[]>();
  /** Every rate the sheet has, each for a grade from its from-date. */
  readonly rates = input.required<Rate[]>();
  /** Every grade this person has been given, each from its from-date. */
  readonly grades = input.required<DatedGrade[]>();
  /** The sheet's periods. */
  readonly periods = input.required<Period[]>();
  /** The ids of the claims selected for a bulk action. */
  readonly selected = input.required<ReadonlySet<number>>();
  /** A claim's selection turned on or off. */
  readonly toggled = output<{ id: number; on: boolean }>();
  /** A claim added or saved, for the sheet's list to take in. */
  readonly saved = output<Claim>();

  protected readonly editingId = signal<number | null>(null);
  protected readonly error = signal<string | null>(null);
  /** The error of each claim's last refused status change, by claim id. */
  /** Whether a submit is waiting for its answer; a second submit meanwhile is ignored. */
  private submitting = false;
  protected readonly rowErrors = signal<Record<number, string>>({});
  /** The reason typed for rejecting each PENDING claim, by claim id. */
  protected readonly rejectReasons = signal<Record<number, string>>({});
  protected readonly fieldId = (name: string) => `claim-form-${name}-${this.personId()}`;

  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    date: new FormControl('', { nonNullable: true }),
    note: new FormControl('', { nonNullable: true }),
    corrects: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
  }

  /** The claim's amount times the rate in force on the claim's date for the person's grade then, divided by 100, rounded
   *  by the claim's rounding policy (half up before the sheet's policy date, else half to even), at least the sheet's floor; n/a with no rate in force then. A claim settled with a
   *  due shows the due fixed then, and one bound by a statement the due bound; an overdue open
   *  (OPEN or PENDING) claim gains its late charge on top. */
  protected dueOf(c: Claim): string {
    const grade = gradeOn(this.grades(), c.date);
    const due = claimDueCents(this.rates().filter((r) => r.grade === grade), c, cents(this.session.floor()), {
      today: this.session.today(), terms: this.session.terms(), latePct: this.session.latePct(),
    }, roundsHalfUp(c, this.claims(), this.session.policyDate(), this.session.today()));
    return due === null ? 'n/a' : money(due);
  }

  /** The claim's date plus the sheet's terms. */
  protected dueByOf(c: Claim): string {
    return dueBy(c, this.session.terms());
  }

  /** Whether the claim is open (OPEN or PENDING) with its due-by before the sheet's today. */
  protected overdueOf(c: Claim): boolean {
    return overdue(c, this.session.terms(), this.session.today());
  }

  /** The name of the period whose dates contain the claim's date; blank when none does. */
  protected periodOf(c: Claim): string {
    return periodOn(this.periods(), c.date)?.name ?? '';
  }

  protected edit(c: Claim): void {
    this.error.set(null);
    this.clearRowError(c.id);
    if (c.status !== 'DRAFT') {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: 'Only a draft claim can be edited; void it and add a new one.' }));
      return;
    }
    if (periodOn(this.periods(), c.date)?.closed) {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: 'This claim is dated in a closed period.' }));
      return;
    }
    this.editingId.set(c.id);
    this.form.setValue({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '' });
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const value = this.form.getRawValue();
    const amount = value.amount.trim();
    if (!CLAIM_AMOUNT_PATTERN.test(amount)) {
      this.error.set('Enter an amount with up to two decimals.');
      return;
    }
    const date = value.date.trim();
    if (date !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.error.set('Enter a date as yyyy-mm-dd.');
      return;
    }
    const corrects = value.corrects.trim();
    if (corrects !== '' && !/^\S{1,120}$/.test(corrects)) {
      this.error.set('Enter the number of the claim corrected as it is shown, without spaces.');
      return;
    }
    const correction = amount.startsWith('-');
    if (correction && corrects === '') {
      this.error.set('A negative amount must name the number of the settled claim it corrects.');
      return;
    }
    const form = { amount, date: date || null, note: value.note, corrects: corrects === '' ? null : corrects };
    const editing = this.editingId();
    this.submitting = true;
    try {
      const claim = editing === null
        ? await this.api.add(sheetId, this.personId(), form)
        : await this.api.update(sheetId, editing, form);
      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
      this.reset();
    } catch (e) {
      this.error.set(claimError(e, correction));
    } finally {
      this.submitting = false;
    }
  }

  protected reasonChanged(id: number, reason: string): void {
    this.clearRowError(id);
    this.rejectReasons.update((rs) => ({ ...rs, [id]: reason }));
  }

  /** Reject a PENDING claim with the reason typed for it; it goes back to OPEN. */
  protected async reject(c: Claim): Promise<void> {
    this.clearRowError(c.id);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const reason = (this.rejectReasons()[c.id] ?? '').trim();
    if (reason === '') {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: 'Enter a reason for rejecting the claim.' }));
      return;
    }
    try {
      const claim = await this.api.reject(sheetId, c.id, reason);
      this.rejectReasons.update(({ [c.id]: _, ...rest }) => rest);
      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: statusError(e, c.openedBy === this.session.user()) }));
    }
  }

  /** Open, settle, approve or void a claim; a move its status does not allow shows an error on the claim. */
  protected async changeStatus(c: Claim, action: ClaimAction): Promise<void> {
    this.clearRowError(c.id);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    try {
      const claim = await this.api.changeStatus(sheetId, c.id, action);
      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: statusError(e, c.openedBy === this.session.user()) }));
    }
  }

  private clearRowError(id: number): void {
    this.rowErrors.update(({ [id]: _, ...rest }) => rest);
  }

  protected reset(): void {
    this.editingId.set(null);
    this.form.reset({ amount: '', date: '', note: '', corrects: '' });
    this.error.set(null);
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import type { Person } from '../people/people-api';

/** An amount of 0.00 or more with up to two decimals. */
export const AMOUNT_PATTERN = /^\d{1,13}(\.\d{1,2})?$/;

/** A claim form's amount: up to two decimals, negative for a correction. */
export const CLAIM_AMOUNT_PATTERN = /^-?\d{1,13}(\.\d{1,2})?$/;

/** DRAFT when added, then OPEN, then SETTLED; a clerk settling one above the clerk limit sends it to
 *  PENDING, which a steward approves (SETTLED) or rejects (back to OPEN). A DRAFT, OPEN or PENDING
 *  claim may be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A move of a claim's status, as the server names it. */
export type ClaimAction = 'open' | 'settle' | 'void' | 'approve';

export interface Claim {
  id: number;
  personId: number;
  /** Always with two decimals, as the server formats it. */
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** The sheet's number for the claim, given when it is opened and kept if it is voided; null while DRAFT.
   *  A sheet-wide number, or under period numbering one within its period (P1-1, X-1 in no period). */
  number: string | null;
  /** The due fixed when the claim was settled, with two decimals; null, so the due is live, for
   *  a claim not SETTLED or settled when its grade had no rate. */
  settledDue: string | null;
  /** The user who opened the claim, who cannot settle it; null while DRAFT. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim: it then shows and totals statedDue,
   *  except while PENDING, when it shows and totals its live figure. */
  stated: boolean;
  /** The due the claim was bound to, with two decimals; null when unbound or n/a then. */
  statedDue: string | null;
  /** The number of the SETTLED claim this correction (a negative amount) corrects; null for others. */
  corrects: string | null;
}

/** Whether a claim is a correction: its amount is negative. */
export function isCorrection(c: Claim): boolean {
  return c.amount.startsWith('-');
}

/** Whether a claim is open: OPEN, or PENDING (handled like an OPEN one). */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Whether a claim's due is bound to statedDue: stated and not PENDING. */
export function isBound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

/** Whether a claim counts toward claimed and due totals: only open (OPEN or PENDING) and SETTLED ones do. */
export function counts(c: Claim): boolean {
  return isOpen(c) || c.status === 'SETTLED';
}

/** A claim's due-by (yyyy-mm-dd): its date plus the sheet's terms in days. */
export function dueBy(c: Claim, terms: number): string {
  const [y, m, d] = c.date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: open (OPEN or PENDING) with its due-by before the sheet's today. */
export function overdue(c: Claim, terms: number, today: string | null): boolean {
  return isOpen(c) && today !== null && dueBy(c, terms) < today;
}

/** Whether a claim's live figures round half up: its date (a correction's, the date of the claim
 *  of its person it corrects, among `theirs`) is before the sheet's policy date (null: blank, the
 *  sheet's today); else they round half to even. */
export function roundsHalfUp(c: Claim, theirs: readonly Claim[], policyDate: string | null, today: string | null): boolean {
  const policy = policyDate ?? today;
  if (policy === null) return false;
  const on = c.corrects === null ? c.date : theirs.find((o) => o.number === c.corrects)?.date ?? c.date;
  return on < policy;
}

export interface ClaimForm {
  amount: string;
  /** null takes the sheet's today. */
  date: string | null;
  note: string;
  /** The number of the claim a correction corrects; null when none is named. */
  corrects: string | null;
}

export interface QuickAddForm {
  name: string;
  amount: string;
}

/** A quick-add's result: the person (just added when personAdded) and their new DRAFT claim. */
export interface QuickAdd {
  person: Person;
  personAdded: boolean;
  claim: Claim;
}

// The claims kept on the active sheet, read and written through the server.
@Injectable({ providedIn: 'root' })
export class ClaimsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** Every claim on the sheet, newest first. */
  list(sheetId: string): Promise<Claim[]> {
    return firstValueFrom(this.http.get<Claim[]>(`${this.url(sheetId)}/claims`, { headers: this.headers() }));
  }

  add(sheetId: string, personId: number, form: ClaimForm): Promise<Claim> {
    return firstValueFrom(
      this.http.post<Claim>(`${this.url(sheetId)}/people/${personId}/claims`, form, { headers: this.headers() }),
    );
  }

  /** Add a DRAFT claim for the person with the name, adding them (grade A) first when new. */
  quickAdd(sheetId: string, form: QuickAddForm): Promise<QuickAdd> {
    return firstValueFrom(this.http.post<QuickAdd>(`${this.url(sheetId)}/quick-add`, form, { headers: this.headers() }));
  }

  update(sheetId: string, id: number, form: ClaimForm): Promise<Claim> {
    return firstValueFrom(this.http.put<Claim>(`${this.url(sheetId)}/claims/${id}`, form, { headers: this.headers() }));
  }

  changeStatus(sheetId: string, id: number, action: ClaimAction): Promise<Claim> {
    return firstValueFrom(
      this.http.post<Claim>(`${this.url(sheetId)}/claims/${id}/${action}`, null, { headers: this.headers() }),
    );
  }

  /** Reject a PENDING claim with a reason: it goes back to OPEN. */
  reject(sheetId: string, id: number, reason: string): Promise<Claim> {
    return firstValueFrom(
      this.http.post<Claim>(`${this.url(sheetId)}/claims/${id}/reject`, { reason }, { headers: this.headers() }),
    );
  }

  /** Open each of the claims, in list order; those that cannot be opened are left as they are. */
  bulkOpen(sheetId: string, ids: number[]): Promise<{ opened: number; refused: number }> {
    return firstValueFrom(this.http.post<{ opened: number; refused: number }>(`${this.url(sheetId)}/claims/bulk-open`, { ids },
      { headers: this.headers() }));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

/** Why a claim form was refused; `correction` says whether its amount was negative. */
export function claimError(e: unknown, correction = false): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter an amount with up to two decimals.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That claim or person is no longer on this sheet.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'Only a draft claim can be edited; void it and add a new one.';
  if (e instanceof HttpErrorResponse && e.status === 423) return 'The date is in a closed period.';
  if (e instanceof HttpErrorResponse && e.status === 422) {
    return correction
      ? "A correction must name the number of a settled claim of this person, and be dated by the person's retirement date."
      : "The date is after the person's retirement date.";
  }
  return 'Something went wrong; try again.';
}

export function quickAddError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a name and an amount of 0.00 or more with up to two decimals.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That name was just added by someone else; try again.';
  if (e instanceof HttpErrorResponse && e.status === 423) return "The sheet's today is in a closed period.";
  if (e instanceof HttpErrorResponse && e.status === 422) return "The sheet's today is after that person's retirement date.";
  return 'Something went wrong; try again.';
}

/** Why a status change was refused; `opener` says whether the user is the one who opened the claim. */
export function statusError(e: unknown, opener: boolean): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a reason for rejecting the claim.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'This claim cannot make that change from its status.';
  if (e instanceof HttpErrorResponse && e.status === 403) {
    return opener ? 'The user who opened this claim cannot settle or approve it.' : 'Only a steward can approve or reject a pending claim.';
  }
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That claim is no longer on this sheet.';
  if (e instanceof HttpErrorResponse && e.status === 423) return 'This claim is dated in a closed period.';
  return 'Something went wrong; try again.';
}

/** An amount in whole cents (negative for a negative amount). */
export function cents(amount: string): number {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const abs = Number(whole) * 100 + Number((frac + '00').slice(0, 2));
  return negative ? -abs : abs;
}

/** Whole cents as an amount with two decimals, a minus sign before a negative one. */
export function money(cents: number): string {
  const abs = Math.abs(cents);
  return `${cents < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}
